// Corpo do nó Code "Embutir perfil" (primeiro nó do onboarding-hook).
// Run Once for All Items. Lê tenant_id do input (webhook), gera o embedding do
// perfil no OpenAI, grava via RPC set_profile_embedding e propaga o tenant_id
// adiante para o nó Rank. O painel chama /webhook/onboarding no cadastro E em
// toda atualização de perfil, então o embedding fica sempre fresco.
// Env: SUPABASE_URL, SUPABASE_SERVICE_KEY, OPENAI_API_KEY, EMBED_MODEL.

const SUPA = $env.SUPABASE_URL
const KEY = $env.SUPABASE_SERVICE_KEY
const OA = $env.OPENAI_API_KEY
const MODEL = $env.EMBED_MODEL || 'text-embedding-3-small'
const h = this.helpers
const supa = { apikey: KEY, Authorization: `Bearer ${KEY}` }

const firstIn = $input.all().length && $input.all()[0].json ? $input.all()[0].json : {}
const tenant = firstIn.tenant_id || (firstIn.body && firstIn.body.tenant_id) || null
if (!tenant) return [{ json: { error: 'sem tenant_id no input' } }]

const profs = await h.httpRequest({
  method: 'GET',
  url: `${SUPA}/rest/v1/profiles?tenant_id=eq.${tenant}&select=target_roles,skills,seniority,headline,professional_history`,
  headers: supa,
  json: true,
})
const p = profs && profs[0]
if (!p) return [{ json: { tenant_id: tenant, warning: 'perfil não encontrado' } }]

const text = [
  (p.target_roles || []).join(', '),
  (p.skills || []).join(', '),
  p.seniority || '',
  p.headline || '',
  p.professional_history ? JSON.stringify(p.professional_history).slice(0, 2000) : '',
].filter(Boolean).join('\n')

const resp = await h.httpRequest({
  method: 'POST',
  url: 'https://api.openai.com/v1/embeddings',
  headers: { Authorization: `Bearer ${OA}`, 'Content-Type': 'application/json' },
  body: { model: MODEL, input: text || '(perfil vazio)' },
  json: true,
})
const vec = resp.data[0].embedding

await h.httpRequest({
  method: 'POST',
  url: `${SUPA}/rest/v1/rpc/set_profile_embedding`,
  headers: { ...supa, 'Content-Type': 'application/json' },
  body: { p_tenant: tenant, p_embedding: JSON.stringify(vec) },
  json: true,
})

if (resp.usage && resp.usage.prompt_tokens) {
  await h.httpRequest({
    method: 'POST', url: `${SUPA}/rest/v1/llm_usage`,
    headers: { ...supa, Prefer: 'return=minimal' },
    body: [{ tenant_id: tenant, workflow: 'embed-profile', model: MODEL, tokens_in: resp.usage.prompt_tokens, tokens_out: 0 }],
    json: true,
  })
}

// Propaga tenant_id para o nó Rank (próximo na cadeia do onboarding).
return [{ json: { tenant_id: tenant, embedded: true } }]

// Corpo do nó Code "Rank por tenant" (workflow rank-daily).
// Run Once for All Items. Orquestra: tenants → RPC de vagas candidatas →
// rank-service /prepare (gates + prompt) → OpenRouter (LLM) → /assemble (score)
// → upsert em job_matches + telemetria em llm_usage.
// Env: SUPABASE_URL, SUPABASE_SERVICE_KEY, RANK_SERVICE_URL, RANK_SERVICE_TOKEN,
//      OPENROUTER_API_KEY, RANK_MODEL (opcional).

const SUPA = $env.SUPABASE_URL
const KEY = $env.SUPABASE_SERVICE_KEY
const RANK = $env.RANK_SERVICE_URL
const RTOK = $env.RANK_SERVICE_TOKEN
const OR = $env.OPENROUTER_API_KEY
const MODEL = $env.RANK_MODEL || 'anthropic/claude-3.5-haiku'
const h = this.helpers
const supaHeaders = { apikey: KEY, Authorization: `Bearer ${KEY}` }

const mapVerdict = (v) => (v === 'pass' || v === 'fail' || v === 'flag' ? v : null)

// tenant_id opcional do input: onboarding-hook (webhook) passa um; o cron não
// passa nada e ranqueia todos os tenants com direito.
const inItems = $input.all()
const firstIn = inItems.length && inItems[0].json ? inItems[0].json : {}
const singleTenant = firstIn.tenant_id || (firstIn.body && firstIn.body.tenant_id) || null

// Billing: no cron, expira os trials vencidos antes de selecionar (mantém o
// status coerente na UI). No modo single (onboarding), não precisa.
if (!singleTenant) {
  try {
    await h.httpRequest({ method: 'POST', url: `${SUPA}/rest/v1/rpc/expire_trials`, headers: { ...supaHeaders, 'Content-Type': 'application/json' }, body: {}, json: true })
  } catch (e) { /* segue mesmo se falhar */ }
}

// Entitlement: pagos ativos, ou trials ainda no prazo.
const nowIso = new Date().toISOString()
const tenantsUrl = singleTenant
  ? `${SUPA}/rest/v1/tenants?id=eq.${singleTenant}&select=id,profiles(*)`
  : `${SUPA}/rest/v1/tenants?subscription_status=eq.active&or=(tier.neq.trial,trial_ends_at.gt.${nowIso})&select=id,profiles(*)`
const tenants = await h.httpRequest({ method: 'GET', url: tenantsUrl, headers: supaHeaders, json: true })

const summary = []
for (const t of tenants) {
  const prof = Array.isArray(t.profiles) ? t.profiles[0] : t.profiles
  if (!prof) continue

  const profile = {
    targetRoles: prof.target_roles || [],
    seniority: prof.seniority || undefined,
    cities: prof.cities || [],
    acceptsWorkModels: prof.accepts_work_models || [],
    languages: prof.languages || [],
    skills: prof.skills || [],
    contractPreference: prof.contract_preference || 'any',
    summary: prof.headline || (prof.professional_history ? JSON.stringify(prof.professional_history) : undefined),
  }

  // Vagas candidatas (recentes, não avaliadas, ordenadas por pgvector).
  const jobsRaw = await h.httpRequest({
    method: 'POST',
    url: `${SUPA}/rest/v1/rpc/jobs_for_tenant`,
    headers: { ...supaHeaders, 'Content-Type': 'application/json' },
    body: { p_tenant: t.id, p_limit: 30, p_days: 3 },
    json: true,
  })
  if (!jobsRaw || !jobsRaw.length) continue

  const jobs = jobsRaw.map((j) => ({
    id: j.id, source: j.source, title: j.title, company: j.company,
    location: j.location, workModel: j.work_model, description: j.description,
    contractType: j.contract_type || null, deadline: j.deadline,
  }))

  // Estágio 1 + prompt.
  const prep = await h.httpRequest({
    method: 'POST', url: `${RANK}/prepare`,
    headers: { Authorization: `Bearer ${RTOK}` },
    body: { profile, jobs }, json: true,
  })

  let judged = { results: [] }
  let usage = {}
  if (prep.survivors && prep.survivors.length) {
    const llm = await h.httpRequest({
      method: 'POST', url: 'https://openrouter.ai/api/v1/chat/completions',
      headers: { Authorization: `Bearer ${OR}`, 'Content-Type': 'application/json' },
      body: {
        model: MODEL, temperature: 0, response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: prep.system },
          { role: 'user', content: prep.user },
        ],
      },
      json: true,
    })
    const content = (llm.choices && llm.choices[0] && llm.choices[0].message && llm.choices[0].message.content) || '{}'
    usage = llm.usage || {}
    judged = await h.httpRequest({
      method: 'POST', url: `${RANK}/assemble`,
      headers: { Authorization: `Bearer ${RTOK}` },
      body: { profile, survivors: prep.survivors, llm: content }, json: true,
    })
  }

  // Linhas de job_matches: vetados (sem score) + avaliados.
  const matchRows = []
  for (const v of prep.vetoed || []) {
    matchRows.push({
      tenant_id: t.id, job_id: v.jobId, status: 'ranked',
      location_verdict: mapVerdict(v.locationVerdict),
      language_verdict: mapVerdict(v.languageVerdict),
      language_note: v.languageNote ?? null,
      gaps: v.gaps || [], strengths: [], model: null,
    })
  }
  for (const r of judged.results || []) {
    matchRows.push({
      tenant_id: t.id, job_id: r.jobId, status: 'ranked',
      score: r.overall ?? null,
      score_technical: r.scores && r.scores.technical,
      score_experience: r.scores && r.scores.experience,
      score_behavioral: r.scores && r.scores.behavioral,
      score_career: r.scores && r.scores.career,
      verdict: r.verdict ?? null,
      location_verdict: mapVerdict(r.locationVerdict),
      language_verdict: mapVerdict(r.languageVerdict),
      language_note: r.languageNote ?? null,
      strengths: r.strengths || [], gaps: r.gaps || [], model: MODEL,
    })
  }

  if (matchRows.length) {
    await h.httpRequest({
      method: 'POST',
      url: `${SUPA}/rest/v1/job_matches?on_conflict=tenant_id,job_id`,
      headers: { ...supaHeaders, Prefer: 'resolution=merge-duplicates,return=minimal' },
      body: matchRows, json: true,
    })
  }

  // Telemetria de custo (cost_brl fica no default 0; conversão de preço é passo futuro).
  if (usage && usage.total_tokens) {
    await h.httpRequest({
      method: 'POST', url: `${SUPA}/rest/v1/llm_usage`,
      headers: { ...supaHeaders, Prefer: 'return=minimal' },
      body: [{
        tenant_id: t.id, workflow: 'rank-daily', model: MODEL,
        tokens_in: usage.prompt_tokens || 0, tokens_out: usage.completion_tokens || 0, meta: usage,
      }],
      json: true,
    })
  }

  summary.push({
    tenant: t.id, candidatas: jobs.length,
    avaliadas: (judged.results || []).length, vetadas: (prep.vetoed || []).length,
  })
}

// Em modo single (onboarding), propaga o tenant_id adiante para o nó Notify.
const out = { tenants: tenants.length, detalhe: summary }
if (singleTenant) out.tenant_id = singleTenant
return [{ json: out }]

// Corpo do nó Code "Notificar" (workflows notify-daily e onboarding-hook).
// Run Once for All Items. Envia o top-N de matches novos por tenant via WhatsApp
// (Evolution API) com fallback e-mail (Resend), registra em notifications e marca
// os matches como 'notified'. Só marca no envio bem-sucedido.
// Env: SUPABASE_URL, SUPABASE_SERVICE_KEY, EVOLUTION_URL, EVOLUTION_INSTANCE,
//      EVOLUTION_API_KEY, RESEND_API_KEY, NOTIFY_FROM_EMAIL,
//      NOTIFY_MIN_SCORE (default 60), NOTIFY_TOP (default 5), PANEL_URL (opcional).

const SUPA = $env.SUPABASE_URL
const KEY = $env.SUPABASE_SERVICE_KEY
const h = this.helpers
const supaHeaders = { apikey: KEY, Authorization: `Bearer ${KEY}` }
const MIN = Number($env.NOTIFY_MIN_SCORE || 60)
const TOP = Number($env.NOTIFY_TOP || 5)
const PANEL = $env.PANEL_URL || ''

// tenant_id opcional (onboarding). Ausente = todos os elegíveis (cron).
const firstIn = $input.all().length && $input.all()[0].json ? $input.all()[0].json : {}
const singleTenant = firstIn.tenant_id || (firstIn.body && firstIn.body.tenant_id) || null

// Quem notificar (RPC): tenants ativos com matches novos + contato.
const targets = await h.httpRequest({
  method: 'POST',
  url: `${SUPA}/rest/v1/rpc/tenants_to_notify`,
  headers: { ...supaHeaders, 'Content-Type': 'application/json' },
  body: { p_tenant: singleTenant },
  json: true,
})

async function sendWhatsApp(number, text) {
  const url = $env.EVOLUTION_URL, inst = $env.EVOLUTION_INSTANCE, key = $env.EVOLUTION_API_KEY
  if (!url || !inst || !key) return false
  await h.httpRequest({
    method: 'POST',
    url: `${url}/message/sendText/${inst}`,
    headers: { apikey: key, 'Content-Type': 'application/json' },
    body: { number, text },
    json: true,
  })
  return true
}

async function sendEmail(to, subject, text) {
  const key = $env.RESEND_API_KEY, from = $env.NOTIFY_FROM_EMAIL
  if (!key || !from || !to) return false
  await h.httpRequest({
    method: 'POST',
    url: 'https://api.resend.com/emails',
    headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
    body: { from, to, subject, text },
    json: true,
  })
  return true
}

const summary = []
for (const t of targets) {
  // Top-N matches novos (ranked, score alto), com dados da vaga embutidos.
  const matches = await h.httpRequest({
    method: 'GET',
    url: `${SUPA}/rest/v1/job_matches?tenant_id=eq.${t.tenant_id}&status=eq.ranked&score=gte.${MIN}&order=score.desc&limit=${TOP}&select=job_id,score,verdict,jobs(title,company,url)`,
    headers: supaHeaders,
    json: true,
  })
  if (!matches || !matches.length) continue

  const lines = matches.map((m) => {
    const j = m.jobs || {}
    return `• ${j.title || 'Vaga'}${j.company ? ' — ' + j.company : ''} (fit ${m.score})\n  ${j.url || ''}`
  })
  const text = `Novas vagas com bom fit pra você:\n\n${lines.join('\n\n')}${PANEL ? `\n\nVer todas: ${PANEL}` : ''}`
  const subject = `${matches.length} nova(s) vaga(s) com bom fit`

  // Envio: WhatsApp com consentimento, senão e-mail.
  let channel = null
  try {
    if (t.whatsapp_number && t.whatsapp_consent_at && (await sendWhatsApp(t.whatsapp_number, text))) {
      channel = 'whatsapp'
    } else if (await sendEmail(t.email, subject, text)) {
      channel = 'email'
    }
  } catch (e) {
    // falha de envio: não marca como notificado, tenta de novo amanhã
    summary.push({ tenant: t.tenant_id, erro: String(e.message || e) })
    continue
  }
  if (!channel) {
    summary.push({ tenant: t.tenant_id, pulado: 'sem canal (WhatsApp sem consentimento e e-mail não configurado)' })
    continue
  }

  const matchIds = matches.map((m) => m.job_id)

  // Registra a notificação.
  await h.httpRequest({
    method: 'POST', url: `${SUPA}/rest/v1/notifications`,
    headers: { ...supaHeaders, Prefer: 'return=minimal' },
    body: [{ tenant_id: t.tenant_id, channel, status: 'sent', match_ids: matchIds, payload: { text }, sent_at: new Date().toISOString() }],
    json: true,
  })

  // Marca os matches enviados como 'notified' (não voltam no próximo envio).
  const inList = matchIds.map((id) => `"${id}"`).join(',')
  await h.httpRequest({
    method: 'PATCH',
    url: `${SUPA}/rest/v1/job_matches?tenant_id=eq.${t.tenant_id}&job_id=in.(${inList})`,
    headers: { ...supaHeaders, Prefer: 'return=minimal' },
    body: { status: 'notified' },
    json: true,
  })

  summary.push({ tenant: t.tenant_id, canal: channel, enviadas: matchIds.length })
}

return [{ json: { alvos: targets.length, detalhe: summary } }]
